import mcp
import asyncio
import json
import sys
from typing import Any, Callable, Dict

class BackendForwarder:
    """Forwards all tool and resource requests to a backend MCP server."""

    def __init__(self, backend_server):
        self.backend = backend_server
        self.proxy = mcp.Server("transparent-proxy")
        self._registered_tools = set()
        self._registered_resources = set()

    async def initialize(self):
        """Discover backend capabilities and register proxy handlers."""
        # Attempt to get tools from backend
        try:
            # Access backend tools directly if it's an in-memory server object
            if hasattr(self.backend, '_tools'):
                for tool_name, tool_func in self.backend._tools.items():
                    await self._register_tool_proxy(tool_name, tool_func)
            if hasattr(self.backend, '_resources'):
                for resource_uri, resource_func in self.backend._resources.items():
                    await self._register_resource_proxy(resource_uri, resource_func)
        except Exception as e:
            # Fallback for network-based backends
            pass

    async def _register_tool_proxy(self, tool_name: str, backend_tool: Callable):
        """Register a tool on proxy that forwards to backend."""
        if tool_name in self._registered_tools:
            return
        self._registered_tools.add(tool_name)

        async def tool_wrapper(**kwargs) -> str:
            try:
                result = await backend_tool(**kwargs)
                return result if isinstance(result, str) else json.dumps(result)
            except Exception as e:
                return json.dumps({"error": str(e)})

        tool_wrapper.__name__ = tool_name
        self.proxy.tool(name=tool_name)(tool_wrapper)

    async def _register_resource_proxy(self, resource_uri: str, backend_resource: Callable):
        """Register a resource on proxy that forwards to backend."""
        if resource_uri in self._registered_resources:
            return
        self._registered_resources.add(resource_uri)

        async def resource_wrapper() -> str:
            try:
                result = await backend_resource()
                return result if isinstance(result, str) else json.dumps(result)
            except Exception as e:
                return json.dumps({"error": str(e)})

        resource_wrapper.__name__ = resource_uri.replace(':', '_').replace('/', '_')
        self.proxy.resource(uri=resource_uri)(resource_wrapper)

    async def run(self):
        """Run the proxy server."""
        await self.initialize()
        async with self.proxy.run_in_stdio():
            await asyncio.sleep(float('inf'))


async def main():
    # Import or obtain reference to backend server instance
    # backend_server = get_backend_server()  # Your backend instance

    # For demonstration, create a simple backend
    backend = mcp.Server("backend")

    @backend.tool()
    async def backend_add(a: int, b: int) -> str:
