        return json.dumps({"result": x * y})

    @backend.resource()
    async def backend_info() -> str:
        return json.dumps({"server": "backend", "version": "1.0"})

    # Create and run transparent proxy
    forwarder = BackendForwarder(backend)
    await forwarder.run()


